1	package com.example.starter.service;
2	
3	import com.example.starter.catalog.DocumentCatalog;
4	import com.example.starter.catalog.InspectionCatalog;
5	import com.example.starter.catalog.InspectionEvaluator;
6	import com.example.starter.catalog.InspectionSpec;
7	import com.example.starter.domain.BindingStatus;
8	import com.example.starter.domain.CustomsDeclaration;
9	import com.example.starter.domain.CustomsStatus;
10	import com.example.starter.domain.EnterpriseProductStatus;
11	import com.example.starter.domain.InspectionRecord;
12	import com.example.starter.domain.PublicityRecord;
13	import com.example.starter.domain.PublicityStatus;
14	import com.example.starter.domain.Review;
15	import com.example.starter.domain.ReviewEvent;
16	import com.example.starter.domain.ReviewStatus;
17	import com.example.starter.domain.SubbatchBinding;
18	import com.example.starter.dto.CorrectRequest;
19	import com.example.starter.dto.DeclareRequest;
20	import com.example.starter.dto.EnterpriseStatusView;
21	import com.example.starter.dto.ErrorResponse;
22	import com.example.starter.dto.InspectionInput;
23	import com.example.starter.dto.LateDocumentRequest;
24	import com.example.starter.dto.LateDocumentResponse;
25	import com.example.starter.dto.ReviewView;
26	import com.example.starter.dto.ServiceResult;
27	import com.example.starter.idempotency.Fingerprints;
28	import com.example.starter.json.JsonSupport;
29	import com.example.starter.repo.CustomsRepository;
30	import com.example.starter.repo.EnterpriseProductStatusRepository;
31	import com.example.starter.repo.IdempotencyRepository;
32	import com.example.starter.repo.ReviewRepository;
33	import com.example.starter.time.BusinessClock;
34	import com.example.starter.time.WorkdayCalculator;
35	import org.springframework.stereotype.Service;
36	import org.springframework.transaction.support.TransactionTemplate;
37	
38	import java.time.Instant;
39	import java.time.LocalDate;
40	import java.time.ZoneId;
41	import java.time.ZoneOffset;
42	import java.util.ArrayList;
43	import java.util.LinkedHashSet;
44	import java.util.List;
45	import java.util.Set;
46	
47	/**
48	 * 疫苗批签发资料审查与公示核心服务。
49	 *
50	 * <p>流转：申报 → 资料审查 → 检验核对 → 综合评定 → 公示 → 签发归档。
51	 * 申报、补正、签发以 requestId 幂等；批号唯一；公示期满生效与异议受理经行锁形成唯一终态。
52	 */
53	@Service
54	public class ReviewService {
55	
56	    /** 补正工作日时限。 */
57	    static final int CORRECTION_WORKDAYS = 5;
58	    /** 公示自然日时长（UTC 日界）。 */
59	    static final int PUBLICITY_DAYS = 7;
60	    /** 恰连续 3 批不合格触发暂停受理。 */
61	    static final int SUSPEND_THRESHOLD = 3;
62	
63	    private static final ZoneId SHANGHAI = ZoneId.of("Asia/Shanghai");
64	
65	    private final ReviewRepository reviewRepository;
66	    private final EnterpriseProductStatusRepository statusRepository;
67	    private final IdempotencyRepository idempotencyRepository;
68	    private final CustomsRepository customsRepository;
69	    private final ReviewViewAssembler assembler;
70	    private final JsonSupport jsonSupport;
71	    private final BusinessClock clock;
72	    private final TransactionTemplate txTemplate;
73	
74	    public ReviewService(ReviewRepository reviewRepository,
75	                         EnterpriseProductStatusRepository statusRepository,
76	                         IdempotencyRepository idempotencyRepository,
77	                         CustomsRepository customsRepository,
78	                         ReviewViewAssembler assembler,
79	                         JsonSupport jsonSupport,
80	                         BusinessClock clock,
81	                         TransactionTemplate txTemplate) {
82	        this.reviewRepository = reviewRepository;
83	        this.statusRepository = statusRepository;
84	        this.idempotencyRepository = idempotencyRepository;
85	        this.customsRepository = customsRepository;
86	        this.assembler = assembler;
87	        this.jsonSupport = jsonSupport;
88	        this.clock = clock;
89	        this.txTemplate = txTemplate;
90	    }
91	
92	    /** 事务内执行业务并返回结果（允许提交 4xx 预期错误结果）。 */
93	    @FunctionalInterface
94	    private interface TxAction {
95	        ServiceResult run();
96	    }
97	
98	    // ============================ 申报 ============================
99	
100	    /**
101	     * 申报受理（requestId 幂等）。资料缺项一次性告知补正；资料齐全则完成资料审查与检验核对。
102	     */
103	    public ServiceResult declare(DeclareRequest request) {
104	        String fingerprint = Fingerprints.declare(request);
105	        return idempotent(request.requestId(), Fingerprints.DECLARE, fingerprint,
106	                () -> doDeclare(request));
107	    }
108	
109	    private ServiceResult doDeclare(DeclareRequest request) {
110	        Instant now = clock.now();
111	
112	        // 暂停受理校验：同企业同品种连续 3 批不合格已暂停的，拒绝受理并转核查。
113	        EnterpriseProductStatus epStatus = statusRepository.find(request.enterpriseName(), request.productName());
114	        if (epStatus == null) {
115	            statusRepository.initIfAbsent(request.enterpriseName(), request.productName(), now);
116	            epStatus = statusRepository.find(request.enterpriseName(), request.productName());
117	        }
118	        if (epStatus.isSuspended()) {
119	            return ServiceResult.status(403, new ErrorResponse("ENTERPRISE_SUSPENDED",
120	                    "该企业同品种已因连续 3 批不合格暂停受理并转核查"));
121	        }
122	
123	        List<String> submitted = normalizeDocuments(request.documents());
124	        List<String> invalidDocs = submitted.stream()
125	                .filter(code -> !DocumentCatalog.requiredDocuments().contains(code))
126	                .toList();
127	        if (!invalidDocs.isEmpty()) {
128	            return ServiceResult.status(400, new ErrorResponse("UNKNOWN_DOCUMENT_CODE",
129	                    "存在合成资料目录之外的资料代码: " + invalidDocs));
130	        }
131	
132	        List<InspectionRecord> inspections = buildInspectionRecords(request.inspections());
133	        if (inspections == null) {
134	            return ServiceResult.status(400, new ErrorResponse("INVALID_INSPECTION",
135	                    "检验项目必须且只能包含合成检验目录中的全部项目，代码不得重复"));
136	        }
137	
138	        List<String> missing = DocumentCatalog.requiredDocuments().stream()
139	                .filter(code -> !submitted.contains(code))
140	                .toList();
141	
142	        Review review = new Review();
143	        review.setEnterpriseName(request.enterpriseName().trim());
144	        review.setProductName(request.productName().trim());
145	        review.setBatchNo(request.batchNo().trim());
146	        review.setDocumentsJson(jsonSupport.write(deduplicate(request.documents())));
147	        review.setDeclaredAt(now);
148	        review.setCreatedAt(now);
149	        review.setUpdatedAt(now);
150	
151	        LocalDate noticeDate = LocalDate.ofInstant(now, SHANGHAI);
152	        if (!missing.isEmpty()) {
153	            // 缺项：一次性告知补正，时限 5 个工作日。
154	            review.setStatus(ReviewStatus.PENDING_CORRECTION);
155	            review.setMissingJson(jsonSupport.write(missing));
156	            review.setCorrectionNoticeDate(noticeDate);
157	            review.setCorrectionDeadline(WorkdayCalculator.plusWorkdays(noticeDate, CORRECTION_WORKDAYS));
158	        } else {
159	            review.setStatus(ReviewStatus.INSPECTION_CHECKED);
160	            review.setMissingJson(null);
161	        }
162	
163	        Long reviewId = reviewRepository.insert(review);
164	        if (reviewId == null) {
165	            // 批号唯一约束落败：同一批号同时刻只允许一个审查流程。
166	            return ServiceResult.status(409, new ErrorResponse("BATCH_ALREADY_ACCEPTED",
167	                    "该批号已存在审查流程，并发申报仅唯一受理"));
168	        }
169	        review.setId(reviewId);
170	        reviewRepository.insertInspections(reviewId, inspections);
171	
172	        reviewRepository.insertEvent(new ReviewEvent(reviewId, "DECLARED",
173	                jsonSupport.write(java.util.Map.of("batchNo", review.getBatchNo())), now));
174	        if (!missing.isEmpty()) {
175	            reviewRepository.insertEvent(new ReviewEvent(reviewId, "CORRECTION_NOTICED",
176	                    jsonSupport.write(java.util.Map.of(
177	                            "missing", missing,
178	                            "deadline", review.getCorrectionDeadline().toString())), now));
179	        } else {
180	            reviewRepository.insertEvent(new ReviewEvent(reviewId, "DOCUMENT_REVIEWED", null, now));
181	            reviewRepository.insertEvent(new ReviewEvent(reviewId, "INSPECTION_CHECKED",
182	                    inspectionSummary(inspections), now));
183	        }
184	        return ServiceResult.ok(assembler.assemble(review, inspections, null));
185	    }
186	
187	    // ============================ 补正 ============================
188	
189	    /**
190	     * 补正受理（requestId 幂等）。恰第 5 个工作日提交仍受理，逾期按撤回处理。
191	     */
192	    public ServiceResult correct(String batchNo, CorrectRequest request) {
193	        String fingerprint = Fingerprints.correct(batchNo, request);
194	        return idempotent(request.requestId(), Fingerprints.CORRECT, fingerprint,
195	                () -> doCorrect(batchNo, request));
196	    }
197	
198	    private ServiceResult doCorrect(String batchNo, CorrectRequest request) {
199	        Instant now = clock.now();
200	        Review review = reviewRepository.lockByBatchNo(batchNo.trim());
201	        if (review == null) {
202	            return ServiceResult.status(404, new ErrorResponse("REVIEW_NOT_FOUND",
203	                    "批号不存在: " + batchNo));
204	        }
205	        if (review.getStatus() == ReviewStatus.ISSUED
206	                || review.getStatus() == ReviewStatus.REJECTED
207	                || review.getStatus() == ReviewStatus.WITHDRAWN
208	                || review.getStatus() == ReviewStatus.OBJECTION_REVIEW) {
209	            return ServiceResult.status(409, new ErrorResponse("REVIEW_FINAL_OR_LOCKED",
210	                    "当前状态 " + review.getStatus() + " 不允许补正"));
211	        }
212	        if (review.getStatus() != ReviewStatus.PENDING_CORRECTION) {
213	            return ServiceResult.status(409, new ErrorResponse("NOT_AWAITING_CORRECTION",
214	                    "该流程不处于待补正状态，当前状态: " + review.getStatus()));
215	        }
216	
217	        LocalDate today = LocalDate.ofInstant(now, SHANGHAI);
218	        if (today.isAfter(review.getCorrectionDeadline())) {
219	            // 逾期未补正：按撤回处理（终态）。
220	            review.setStatus(ReviewStatus.WITHDRAWN);
221	            review.setUpdatedAt(now);
222	            reviewRepository.update(review);
223	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "WITHDRAWN",
224	                    jsonSupport.write(java.util.Map.of(
225	                            "deadline", review.getCorrectionDeadline().toString(),
226	                            "submittedDate", today.toString())), now));
227	            return ServiceResult.status(400, new ErrorResponse("CORRECTION_OVERDUE_WITHDRAWN",
228	                    "补正已逾期（截止 " + review.getCorrectionDeadline() + "），按撤回处理"));
229	        }
230	
231	        List<String> submitted = normalizeDocuments(request.documents());
232	        List<String> invalidDocs = submitted.stream()
233	                .filter(code -> !DocumentCatalog.requiredDocuments().contains(code))
234	                .toList();
235	        if (!invalidDocs.isEmpty()) {
236	            return ServiceResult.status(400, new ErrorResponse("UNKNOWN_DOCUMENT_CODE",
237	                    "存在合成资料目录之外的资料代码: " + invalidDocs));
238	        }
239	
240	        Set<String> merged = new LinkedHashSet<>(jsonSupport.readStringList(review.getDocumentsJson()));
241	        merged.addAll(submitted);
242	        List<String> stillMissing = DocumentCatalog.requiredDocuments().stream()
243	                .filter(code -> !merged.contains(code))
244	                .toList();
245	        if (!stillMissing.isEmpty()) {
246	            // 一次性告知后补正仍缺项：拒绝本次补正，维持原待补正状态与截止日。
247	            return ServiceResult.status(400, new ErrorResponse("CORRECTION_STILL_INCOMPLETE",
248	                    "补正资料仍缺项: " + stillMissing));
249	        }
250	
251	        review.setDocumentsJson(jsonSupport.write(List.copyOf(merged)));
252	        review.setMissingJson(null);
253	        review.setCorrectedAt(now);
254	        review.setStatus(ReviewStatus.INSPECTION_CHECKED);
255	        review.setUpdatedAt(now);
256	        reviewRepository.update(review);
257	
258	        List<InspectionRecord> inspections = reviewRepository.listInspections(review.getId());
259	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "CORRECTION_ACCEPTED",
260	                jsonSupport.write(java.util.Map.of("submittedDate", today.toString())), now));
261	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "DOCUMENT_REVIEWED", null, now));
262	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "INSPECTION_CHECKED",
263	                inspectionSummary(inspections), now));
264	        return ServiceResult.ok(assembler.assemble(review, inspections,
265	                reviewRepository.findPublicity(review.getId())));
266	    }
267	
268	    // ============================ 综合评定 + 启动公示 ============================
269	
270	    /**
271	     * 综合评定：复算检验链，关键项目（效力、无菌、异常毒性）须全项合格。
272	     * 评定通过随即启动 7 个自然日公示；不通过则驳回并累计企业连续不合格批次，恰连续 3 批暂停受理。
273	     */
274	    public ServiceResult evaluate(String batchNo) {
275	        return txTemplate.execute(status -> {
276	            Instant now = clock.now();
277	            Review review = reviewRepository.lockByBatchNo(batchNo.trim());
278	            if (review == null) {
279	                throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
280	            }
281	            if (review.getStatus() != ReviewStatus.INSPECTION_CHECKED) {
282	                throw new BusinessException(409, "INVALID_EVALUATION_STATE",
283	                        "仅检验核对完成的批次可综合评定，当前状态: " + review.getStatus());
284	            }
285	
286	            List<InspectionRecord> records = reviewRepository.listInspections(review.getId());
287	            // 复算：不信任存储的 qualified，按限值重新判定。
288	            boolean allQualified = true;
289	            boolean criticalQualified = true;
290	            for (InspectionRecord record : records) {
291	                InspectionSpec spec = InspectionCatalog.find(record.getItemCode());
292	                boolean qualified = spec != null
293	                        && InspectionEvaluator.isQualified(spec, record.getMeasuredValue());
294	                record.setQualified(qualified);
295	                allQualified &= qualified;
296	                if (record.isCritical()) {
297	                    criticalQualified &= qualified;
298	                }
299	            }
300	            boolean passed = allQualified && criticalQualified;
301	
302	            review.setConclusion(passed ? "PASS" : "FAIL");
303	            review.setUpdatedAt(now);
304	            if (!passed) {
305	                review.setStatus(ReviewStatus.REJECTED);
306	                reviewRepository.update(review);
307	                EnterpriseProductStatus updated = statusRepository.incrementFailed(
308	                        review.getEnterpriseName(), review.getProductName(), now);
309	                String payload = jsonSupport.write(java.util.Map.of(
310	                        "consecutiveFailed", updated.getConsecutiveFailed(),
311	                        "criticalQualified", criticalQualified));
312	                reviewRepository.insertEvent(new ReviewEvent(review.getId(), "EVALUATION_FAILED", payload, now));
313	                if (updated.getConsecutiveFailed() == SUSPEND_THRESHOLD) {
314	                    reviewRepository.insertEvent(new ReviewEvent(review.getId(), "SUSPENSION_TRIGGERED",
315	                            jsonSupport.write(java.util.Map.of(
316	                                    "enterpriseName", review.getEnterpriseName(),
317	                                    "productName", review.getProductName(),
318	                                    "consecutiveFailed", updated.getConsecutiveFailed())), now));
319	                }
320	                return ServiceResult.ok(assembler.assemble(review, records, null));
321	            }
322	
323	            // 评定通过：连续不合格计数清零并启动公示（UTC 日界，恰第 7 日期满）。
324	            statusRepository.resetFailed(review.getEnterpriseName(), review.getProductName(), now);
325	            LocalDate startUtc = LocalDate.ofInstant(now, ZoneOffset.UTC);
326	            LocalDate endUtc = startUtc.plusDays(PUBLICITY_DAYS);
327	            review.setStatus(ReviewStatus.PUBLICIZING);
328	            review.setPublicityStartUtc(startUtc);
329	            review.setPublicityEndUtc(endUtc);
330	            reviewRepository.update(review);
331	
332	            PublicityRecord publicity = new PublicityRecord();
333	            publicity.setReviewId(review.getId());
334	            publicity.setStartUtcDate(startUtc);
335	            publicity.setEndUtcDate(endUtc);
336	            publicity.setStatus(PublicityStatus.PUBLICIZING);
337	            reviewRepository.insertPublicity(publicity);
338	
339	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "EVALUATION_PASSED", null, now));
340	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "PUBLICITY_STARTED",
341	                    jsonSupport.write(java.util.Map.of("startUtc", startUtc.toString(),
342	                            "endUtc", endUtc.toString())), now));
343	            return ServiceResult.ok(assembler.assemble(review, records, publicity));
344	        });
345	    }
346	
347	    // ============================ 公示：异议 / 期满生效竞态 ============================
348	
349	    /**
350	     * 公示期内异议受理，转复核。公示期满（UTC 日期到达 endUtc，恰第 7 日）后不再受理。
351	     */
352	    public ServiceResult acceptObjection(String batchNo) {
353	        return txTemplate.execute(status -> {
354	            Instant now = clock.now();
355	            Review review = reviewRepository.lockByBatchNo(batchNo.trim());
356	            if (review == null) {
357	                throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
358	            }
359	            PublicityRecord publicity = reviewRepository.lockPublicity(review.getId());
360	            if (publicity == null) {
361	                throw new BusinessException(409, "NO_PUBLICITY", "该批次尚未进入公示，不能受理异议");
362	            }
363	            if (publicity.getStatus() == PublicityStatus.OBJECTION_REVIEW) {
364	                throw new BusinessException(409, "OBJECTION_ALREADY_ACCEPTED", "异议已受理，正在复核中");
365	            }
366	            if (publicity.getStatus() == PublicityStatus.EFFECTIVE) {
367	                throw new BusinessException(409, "PUBLICITY_ALREADY_EFFECTIVE",
368	                        "公示已期满生效，异议不再受理");
369	            }
370	            LocalDate todayUtc = LocalDate.ofInstant(now, ZoneOffset.UTC);
371	            if (!todayUtc.isBefore(publicity.getEndUtcDate())) {
372	                // 恰第 7 个自然日已届日界：期满，异议不予受理。
373	                throw new BusinessException(409, "PUBLICITY_PERIOD_ENDED",
374	                        "公示已于 " + publicity.getEndUtcDate() + "（UTC）期满，异议不再受理");
375	            }
376	            publicity.setStatus(PublicityStatus.OBJECTION_REVIEW);
377	            publicity.setObjectionAt(now);
378	            reviewRepository.updatePublicity(publicity);
379	            review.setStatus(ReviewStatus.OBJECTION_REVIEW);
380	            review.setUpdatedAt(now);
381	            reviewRepository.update(review);
382	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "OBJECTION_ACCEPTED", null, now));
383	            return ServiceResult.ok(assembler.assemble(review,
384	                    reviewRepository.listInspections(review.getId()), publicity));
385	        });
386	    }
387	
388	    /**
389	     * 公示期满生效：仅当 UTC 日期恰到达或超过期满日，且无异议受理时生效，形成唯一终态。
390	     * 已生效重复调用幂等返回；异议受理中的不生效。
391	     */
392	    public ServiceResult settlePublicity(String batchNo) {
393	        return txTemplate.execute(status -> {
394	            Instant now = clock.now();
395	            Review review = reviewRepository.lockByBatchNo(batchNo.trim());
396	            if (review == null) {
397	                throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
398	            }
399	            PublicityRecord publicity = reviewRepository.lockPublicity(review.getId());
400	            if (publicity == null) {
401	                throw new BusinessException(409, "NO_PUBLICITY", "该批次尚未进入公示");
402	            }
403	            if (publicity.getStatus() == PublicityStatus.EFFECTIVE) {
404	                return ServiceResult.ok(assembler.assemble(review,
405	                        reviewRepository.listInspections(review.getId()), publicity));
406	            }
407	            if (publicity.getStatus() == PublicityStatus.OBJECTION_REVIEW) {
408	                throw new BusinessException(409, "UNDER_OBJECTION_REVIEW",
409	                        "公示期内异议已受理并转复核，不能期满生效");
410	            }
411	            LocalDate todayUtc = LocalDate.ofInstant(now, ZoneOffset.UTC);
412	            if (todayUtc.isBefore(publicity.getEndUtcDate())) {
413	                throw new BusinessException(409, "PUBLICITY_NOT_EXPIRED",
414	                        "公示尚未期满，期满日（UTC）为 " + publicity.getEndUtcDate());
415	            }
416	            // 恰第 7 日期满：生效，与异议受理互斥，行锁保证唯一终态。
417	            publicity.setStatus(PublicityStatus.EFFECTIVE);
418	            publicity.setEffectiveAt(now);
419	            reviewRepository.updatePublicity(publicity);
420	            review.setStatus(ReviewStatus.PUBLICITY_EFFECTIVE);
421	            review.setUpdatedAt(now);
422	            reviewRepository.update(review);
423	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "PUBLICITY_EFFECTIVE",
424	                    jsonSupport.write(java.util.Map.of("endUtc", publicity.getEndUtcDate().toString())), now));
425	            return ServiceResult.ok(assembler.assemble(review,
426	                    reviewRepository.listInspections(review.getId()), publicity));
427	        });
428	    }
429	
430	    // ============================ 签发归档（终态） ============================
431	
432	    /**
433	     * 签发归档（requestId 幂等）。仅公示期满生效可签发；重复归档幂等成功。
434	     */
435	    public ServiceResult issue(String batchNo, com.example.starter.dto.IssueRequest request) {
436	        String fingerprint = Fingerprints.issue(batchNo, request);
437	        return idempotent(request.requestId(), Fingerprints.ISSUE, fingerprint,
438	                () -> doIssue(batchNo));
439	    }
440	
441	    private ServiceResult doIssue(String batchNo) {
442	        Instant now = clock.now();
443	        String trimmedBatchNo = batchNo.trim();
444	
445	        // 先用不加锁探测确定子批是否为进口绑定；进口子批按固定顺序
446	        // customs_declaration → subbatch_binding → batch_review 加锁，与撤销/撤回互斥序列化。
447	        Review probe = reviewRepository.findByBatchNo(trimmedBatchNo);
448	        if (probe == null) {
449	            return ServiceResult.status(404, new ErrorResponse("REVIEW_NOT_FOUND", "批号不存在: " + batchNo));
450	        }
451	        SubbatchBinding binding = customsRepository.findBindingByReviewId(probe.getId());
452	        CustomsDeclaration customs = null;
453	        if (binding != null) {
454	            customs = customsRepository.lockById(binding.getCustomsDeclarationId());
455	            binding = customsRepository.lockBindingByReviewId(probe.getId());
456	        }
457	        Review review = reviewRepository.lockById(probe.getId());
458	
459	        if (review.getStatus() == ReviewStatus.ISSUED) {
460	            // 终态重复归档：幂等成功。
461	            return ServiceResult.ok(assembler.assemble(review));
462	        }
463	        if (review.getStatus() != ReviewStatus.PUBLICITY_EFFECTIVE) {
464	            return ServiceResult.status(409, new ErrorResponse("NOT_ISSUEABLE",
465	                    "仅公示期满生效的批次可签发归档，当前状态: " + review.getStatus()));
466	        }
467	
468	        if (binding != null) {
469	            // 进口子批：事务内重查通关单，未撤销且 now 严格早于有效截止；恰截止即拒绝。
470	            // 撤销与签发竞争由提交顺序唯一决定，不能拿先前公示通过绕过新失效。
471	            if (customs.getStatus() == CustomsStatus.REVOKED) {
472	                return ServiceResult.status(422, new ErrorResponse("CUSTOMS_REVOKED_BLOCKS_ISSUE",
473	                        "通关单已撤销，未签发子批预占已释放，签发被阻断: " + customs.getCustomsNo()));
474	            }
475	            if (!now.isBefore(customs.getValidUntil())) {
476	                return ServiceResult.status(422, new ErrorResponse("CUSTOMS_EXPIRED",
477	                        "通关单有效截止 " + customs.getValidUntil() + "，恰截止或已过截止不得签发"));
478	            }
479	            if (binding.getStatus() != BindingStatus.RESERVED) {
480	                return ServiceResult.status(422, new ErrorResponse("SUBBATCH_RESERVATION_NOT_HELD",
481	                        "子批预占不处于可核销状态（已释放/已核销），不能签发: "
482	                                + binding.getStatus()));
483	            }
484	
485	            int qty = binding.getDeclaredQuantity();
486	            // 原子核销：同一事务内把本子批预占转为已核销，并扣减通关单余量，
487	            // 不可能出现已发证而余量未扣（行锁 + ck_customs_quantity_bounds 兜底）。
488	            binding.setStatus(BindingStatus.WRITTEN_OFF);
489	            binding.setWrittenOffAt(now);
490	            binding.setVersion(binding.getVersion() + 1);
491	            binding.setUpdatedAt(now);
492	            customsRepository.updateBinding(binding);
493	
494	            customs.setReservedQuantity(customs.getReservedQuantity() - qty);
495	            customs.setWrittenOffQuantity(customs.getWrittenOffQuantity() + qty);
496	            customs.setVersion(customs.getVersion() + 1);
497	            customs.setUpdatedAt(now);
498	            customsRepository.update(customs);
499	
500	            markIssued(review, now);
501	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "CUSTOMS_WRITTEN_OFF",
502	                    jsonSupport.write(java.util.Map.of(
503	                            "customsNo", customs.getCustomsNo(),
504	                            "writtenOffQuantity", qty,
505	                            "totalWrittenOff", customs.getWrittenOffQuantity())), now));
506	            return ServiceResult.ok(assembler.assemble(review));
507	        }
508	
509	        // 国内批次：不加通关门禁，沿用原签发归档逻辑。
510	        markIssued(review, now);
511	        return ServiceResult.ok(assembler.assemble(review));
512	    }
513	
514	    /** 置签发归档终态并登记事件。 */
515	    private void markIssued(Review review, Instant now) {
516	        review.setStatus(ReviewStatus.ISSUED);
517	        review.setIssuedAt(now);
518	        review.setUpdatedAt(now);
519	        reviewRepository.update(review);
520	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "ISSUED_ARCHIVED", null, now));
521	    }
522	
523	    /**
524	     * 归档后迟到资料：仅登记迟到事件，不改变终态；非终态上报拒绝。
525	     */
526	    public ServiceResult reportLateDocument(String batchNo, LateDocumentRequest request) {
527	        return txTemplate.execute(status -> {
528	            Instant now = clock.now();
529	            Review review = reviewRepository.lockByBatchNo(batchNo.trim());
530	            if (review == null) {
531	                throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
532	            }
533	            if (review.getStatus() != ReviewStatus.ISSUED) {
534	                throw new BusinessException(409, "REVIEW_NOT_ARCHIVED",
535	                        "仅签发归档后的迟到资料按迟到事件登记，当前状态: " + review.getStatus());
536	            }
537	            List<String> documents = normalizeDocuments(request.documents());
538	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "LATE_DOCUMENT",
539	                    jsonSupport.write(java.util.Map.of("documents", documents)), now));
540	            return ServiceResult.ok(new LateDocumentResponse(review.getBatchNo(),
541	                    review.getStatus().name(), documents.size(),
542	                    "批次已签发归档，迟到资料仅登记迟到事件，不改变终态"));
543	        });
544	    }
545	
546	    // ============================ 查询（可复算） ============================
547	
548	    /** 查询审查全量视图（资料核对表、检验链、公示记录）。 */
549	    public ReviewView getReview(String batchNo) {
550	        Review review = reviewRepository.findByBatchNo(batchNo.trim());
551	        if (review == null) {
552	            throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
553	        }
554	        return assembler.assemble(review);
555	    }
556	
557	    /** 查询企业-品种受理状态（连续不合格计数、暂停标记）。 */
558	    public EnterpriseStatusView getEnterpriseStatus(String enterprise, String product) {
559	        EnterpriseProductStatus status = statusRepository.find(enterprise.trim(), product.trim());
560	        if (status == null) {
561	            return new EnterpriseStatusView(enterprise.trim(), product.trim(), 0, false, null);
562	        }
563	        return new EnterpriseStatusView(status.getEnterpriseName(), status.getProductName(),
564	                status.getConsecutiveFailed(), status.isSuspended(), status.getSuspendedAt());
565	    }
566	
567	    /** 读取事件流水（资料核对表、检验链、公示链均可随事件复算）。 */
568	    public List<java.util.Map<String, Object>> listEvents(String batchNo) {
569	        Review review = reviewRepository.findByBatchNo(batchNo.trim());
570	        if (review == null) {
571	            throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
572	        }
573	        return reviewRepository.listEvents(review.getId()).stream()
574	                .map(event -> java.util.Map.<String, Object>of(
575	                        "seq", event.getId(),
576	                        "eventType", event.getEventType(),
577	                        "payload", event.getPayload() == null ? "" : event.getPayload(),
578	                        "eventAt", event.getEventAt()))
579	                .toList();
580	    }
581	
582	    // ============================ 幂等模板 ============================
583	
584	    /**
585	     * requestId 幂等执行：同键同参返回首次结果；同键异参 409 且不触碰审查状态。
586	     * 占位记录与业务在同一事务内提交，并发同键由主键竞争唯一序列化。
587	     */
588	    private ServiceResult idempotent(String requestId, String operation, String fingerprint, TxAction action) {
589	        var existing = idempotencyRepository.find(requestId);
590	        if (existing != null) {
591	            return replayOrConflict(existing, fingerprint);
592	        }
593	        try {
594	            return txTemplate.execute(status -> {
595	                idempotencyRepository.insertPlaceholder(requestId, operation, fingerprint, clock.now());
596	                ServiceResult result = action.run();
597	                idempotencyRepository.finalize(requestId, result.httpStatus(),
598	                        jsonSupport.write(result.body()));
599	                return result;
600	            });
601	        } catch (org.springframework.dao.DataAccessException ex) {
602	            // 并发同键：首个事务持锁，落败方可能收到唯一键冲突或锁等待超时；
603	            // 等待首事务提交后读取首次结果重放。
604	            var winner = idempotencyRepository.find(requestId);
605	            if (winner == null) {
606	                winner = awaitIdempotencyRecord(requestId);
607	            }
608	            return replayOrConflict(winner, fingerprint);
609	        }
610	    }
611	
612	    private ServiceResult replayOrConflict(com.example.starter.domain.IdempotencyRecord record,
613	                                           String requestFingerprint) {
614	        if (!record.getFingerprint().equals(requestFingerprint)) {
615	            return ServiceResult.status(409, new ErrorResponse("IDEMPOTENCY_FINGERPRINT_MISMATCH",
616	                    "同一 requestId 携带了不同业务参数，请求被拒绝且审查状态不变"));
617	        }
618	        return ServiceResult.status(record.getHttpStatus(), jsonSupport.readObject(record.getResponseJson()));
619	    }
620	
621	    private com.example.starter.domain.IdempotencyRecord awaitIdempotencyRecord(String requestId) {
622	        for (int i = 0; i < 200; i++) {
623	            var record = idempotencyRepository.find(requestId);
624	            if (record != null) {
625	                return record;
626	            }
627	            try {
628	                Thread.sleep(10);
629	            } catch (InterruptedException ie) {
630	                Thread.currentThread().interrupt();
631	                throw new BusinessException(500, "IDEMPOTENCY_WAIT_INTERRUPTED", "等待首次请求结果时被中断");
632	            }
633	        }
634	        throw new BusinessException(500, "IDEMPOTENCY_RECORD_MISSING",
635	                "并发幂等记录缺失: " + requestId);
636	    }
637	
638	    // ============================ 内部辅助 ============================
639	
640	    /**
641	     * 按合成检验目录构建检验链并逐项复算；项目缺失、未知或重复时返回 null。
642	     */
643	    private List<InspectionRecord> buildInspectionRecords(List<InspectionInput> inputs) {
644	        Set<String> codes = new LinkedHashSet<>();
645	        for (InspectionInput input : inputs) {
646	            if (!codes.add(input.itemCode().trim())) {
647	                return null;
648	            }
649	        }
650	        if (codes.size() != InspectionCatalog.all().size()) {
651	            return null;
652	        }
653	        List<InspectionRecord> records = new ArrayList<>();
654	        for (InspectionSpec spec : InspectionCatalog.all()) {
655	            InspectionInput input = inputs.stream()
656	                    .filter(i -> i.itemCode().trim().equals(spec.itemCode()))
657	                    .findFirst()
658	                    .orElse(null);
659	            if (input == null) {
660	                return null;
661	            }
662	            InspectionRecord record = new InspectionRecord();
663	            record.setItemCode(spec.itemCode());
664	            record.setItemName(spec.itemName());
665	            record.setCritical(spec.critical());
666	            record.setMeasuredValue(input.measuredValue().trim());
667	            record.setComparison(spec.comparison().name());
668	            String primaryLimit = spec.limitMin() != null
669	                    ? spec.limitMin().toPlainString()
670	                    : spec.limitMax() != null ? spec.limitMax().toPlainString() : spec.passText();
671	            record.setLimitValue(primaryLimit);
672	            record.setLimitMax(spec.limitMax() == null ? null : spec.limitMax().toPlainString());
673	            record.setQualified(InspectionEvaluator.isQualified(spec, input.measuredValue()));
674	            records.add(record);
675	        }
676	        return records;
677	    }
678	
679	    private List<String> normalizeDocuments(List<String> documents) {
680	        return documents.stream().map(String::trim).filter(code -> !code.isEmpty()).sorted().distinct().toList();
681	    }
682	
683	    private List<String> deduplicate(List<String> documents) {
684	        return new ArrayList<>(new LinkedHashSet<>(documents.stream().map(String::trim).toList()));
685	    }
686	
687	    private String inspectionSummary(List<InspectionRecord> records) {
688	        return jsonSupport.write(records.stream()
689	                .map(r -> java.util.Map.of("itemCode", r.getItemCode(),
690	                        "critical", r.isCritical(),
691	                        "qualified", r.isQualified()))
692	                .toList());
693	    }
694	}
