23	public final class Fingerprints {
24	
25	    public static final String DECLARE = "DECLARE";
26	    public static final String CORRECT = "CORRECT";
27	    public static final String ISSUE = "ISSUE";
28	    public static final String CUSTOMS_REGISTER = "CUSTOMS_REGISTER";
29	    public static final String CUSTOMS_BIND = "CUSTOMS_BIND";
