37	    /** 申报指纹：requestId + 企业/品种/批号 + 资料目录 + 全部检验实测值。 */
38	    public static String declare(DeclareRequest request) {
39	        List<String> documents = sorted(request.documents());
40	        List<String> inspections = request.inspections().stream()
41	                .map(Fingerprints::inspection)
42	                .sorted()
43	                .toList();
44	        String canonical = String.join("|",
45	                DECLARE,
46	                request.requestId(),
47	                request.enterpriseName().trim(),
48	                request.productName().trim(),
49	                request.batchNo().trim(),
50	                String.join(",", documents),
51	                String.join(",", inspections));
52	        return sha256(canonical);
53	    }
