55	    /** 补正指纹：requestId + 批号 + 补正后完整资料目录。 */
56	    public static String correct(String batchNo, CorrectRequest request) {
57	        String canonical = String.join("|",
58	                CORRECT,
59	                request.requestId(),
60	                batchNo.trim(),
61	                String.join(",", sorted(request.documents())));
62	        return sha256(canonical);
63	    }
