65	    /** 签发指纹：requestId + 批号。 */
66	    public static String issue(String batchNo, IssueRequest request) {
67	        String canonical = String.join("|",
68	                ISSUE,
69	                request.requestId(),
70	                batchNo.trim());
71	        return sha256(canonical);
72	    }
