82	                .field(request.productName())
83	                .field(request.validUntil() == null ? null : request.validUntil().toString())
84	                .number(request.totalQuantity())
85	                .field(request.at() == null ? null : request.at().toString());
86	        return sha256(cb.build());
87	    }
