90	    public static String customsBind(CustomsBindRequest request) {
91	        CanonicalBuilder cb = new CanonicalBuilder(CUSTOMS_BIND);
92	        cb.field(request.requestId())
93	                .field(request.customsNo())
94	                .field(request.batchNo())
95	                .number(request.declaredQuantity())
96	                .number(request.expectedVersion())
97	                .field(request.at() == null ? null : request.at().toString());
98	        return sha256(cb.build());
99	    }
