101	    /** 通关单撤销指纹：操作 + 时刻 + 通关单号 + 期望版本。 */
102	    public static String customsRevoke(CustomsRevokeRequest request) {
103	        CanonicalBuilder cb = new CanonicalBuilder(CUSTOMS_REVOKE);
104	        cb.field(request.requestId())
105	                .field(request.customsNo())
106	                .number(request.expectedVersion())
107	                .field(request.at() == null ? null : request.at().toString());
108	        return sha256(cb.build());
109	    }
