111	    /** 通关单修订指纹：操作 + 时刻 + 通关单号 + 新总支数 + 期望版本。 */
112	    public static String customsAmend(CustomsAmendRequest request) {
113	        CanonicalBuilder cb = new CanonicalBuilder(CUSTOMS_AMEND);
114	        cb.field(request.requestId())
115	                .field(request.customsNo())
