132	    /**
133	     * 结构化无歧义归一化构造器：每个字段写为 {@code <UTF-8 字节长度>:<内容>}，
134	     * 字段间以换行分隔；集合先写元素个数，再逐元素长度前缀。
135	     * 这样即使合法文本本身含 ":"、换行等分隔符也无法伪造字段边界。
136	     */
137	    static final class CanonicalBuilder {
138	        private final StringBuilder sb = new StringBuilder();
139	
140	        CanonicalBuilder(String operation) {
141	            appendRaw(operation);
142	        }
143	
144	        CanonicalBuilder field(String value) {
145	            sb.append('\n');
146	            appendRaw(value == null ? "" : value);
147	            return this;
148	        }
149	
150	        CanonicalBuilder number(long value) {
151	            return field(Long.toString(value));
152	        }
153	
154	        CanonicalBuilder list(List<String> values) {
155	            sb.append('\n').append("L").append(values.size());
156	            for (String value : values) {
157	                sb.append('\n');
158	                appendRaw(value == null ? "" : value);
159	            }
160	            return this;
161	        }
162	
163	        String build() {
164	            return sb.toString();
165	        }
166	
167	        private void appendRaw(String value) {
168	            byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
169	            sb.append(bytes.length).append(':').append(value);
170	        }
171	    }
