// ============================ 冷链证据合成辅助 ============================

/**
 * 构造单片段合格读数链：从 start 到 end 每 5 分钟一个样本（含两端），温度 5℃。
 * 要求 (end-start) 为 5 分钟的整数倍。
 */
protected static List<ReadingInput> readingsEvery5Min(Instant start, Instant end, String temp) {
    List<ReadingInput> readings = new ArrayList<>();
    int seq = 1;
